// globalAttributeFloor is the lowest global attribute id; the globals are
// the dispatcher's, not the definition's.
const globalAttributeFloor = 0xFFF0

// header opens every generated file. The SPDX lines are the module's
// license header (license_header_test.go checks every .go file); the
// "Code generated … DO NOT EDIT." line is the form Go tooling recognises.
const header = `// SPDX-License-Identifier: MIT
// Copyright (C) 2026 SukramJ.

// Code generated by script/clustergen from parity/schema.json. DO NOT EDIT.

`

// output is one generated cluster package.
type output struct {
	Package string
	Source  []byte // definition_gen.go
	Test    []byte // definition_gen_test.go
}

// kind is the encoded shape of a value.
type kind string

const (
	kindAny     kind = "Any"
	kindBool    kind = "Bool"
	kindUint    kind = "Uint"
	kindInt     kind = "Int"
	kindFloat32 kind = "Float32"
	kindFloat64 kind = "Float64"
	kindString  kind = "String"
	kindBytes   kind = "Bytes"
	kindEnum    kind = "Enum"
	kindBitmap  kind = "Bitmap"
	kindStruct  kind = "Struct"
	kindList    kind = "List"
)

// typeInfo is a resolved value type.
type typeInfo struct {
	name   string // the stated type name
	kind   kind
	bits   int
	goType string    // the Go type, without nullable / optional wrapping
	dt     *dataInfo // a named enum, bitmap or struct
	elem   *fieldInfo
}

// fieldInfo is a resolved field (or list entry).
type fieldInfo struct {
	id        uint32
	name      string // matter.js name
	goName    string
	t         typeInfo
	v         *value
	mandatory bool
	nullable  bool
}

// dataInfo is a datatype the package declares.
type dataInfo struct {
	dt     *datatype
	goName string
	kind   kind
	bits   int
	fields []*fieldInfo // struct fields
}

// payload is a struct type the package declares for a command or event
// payload or an anonymous struct.
type payload struct {
	goName   string
	what     string // matter.js name, for messages
	fields   []*fieldInfo
	response *element // set on a response command payload
	command  *element // set on a command payload
	event    *element // set on an event payload
}

type generator struct {
	snap     *snapshot
	c        *cluster
	pkg      string
	used     map[string]string
	data     map[string]*dataInfo
	dataList []*dataInfo
	payloads []*payload
	anon     []*payload
	attrType map[uint32]typeInfo
}

// generate produces the package of cluster name.
func generate(snap *snapshot, name string) (*output, error) {
	c := snap.cluster(name)
	if c == nil {
		return nil, fmt.Errorf("no cluster %s in the snapshot", name)
	}
	g := &generator{
		snap: snap, c: c, pkg: packageName(c.Name),
		used: map[string]string{}, data: map[string]*dataInfo{}, attrType: map[uint32]typeInfo{},
	}
	for _, id := range []string{"ClusterID", "Name", "Revision", "Definition", "Feature"} {
		g.used[id] = "package identifier"
	}
	if err := g.collect(); err != nil {
		return nil, fmt.Errorf("%s: %w", c.Name, err)
	}
	src, err := g.source()
	if err != nil {
		return nil, fmt.Errorf("%s: %w", c.Name, err)
	}
	test, err := g.test()
	if err != nil {
		return nil, fmt.Errorf("%s: %w", c.Name, err)
	}
	return &output{Package: g.pkg, Source: src, Test: test}, nil
}

func (g *generator) claim(id, what string) error {
	if prev, ok := g.used[id]; ok {
		return fmt.Errorf("identifier %s for %s collides with %s", id, what, prev)
	}
	g.used[id] = what
	return nil
}

// lookupDatatype finds a named enum, bitmap or struct: the cluster's own
// (inherited ones included), then the global ones.
func (g *generator) lookupDatatype(name string) *datatype {
	for _, d := range g.c.Datatypes {
		if d.Name == name {
			return d
		}
	}
	for _, d := range g.snap.GlobalDatatypes {
		if d.Name == name {
			return d
		}
	}
	return nil
}

// declare registers a datatype for declaration, once.
func (g *generator) declare(d *datatype) (*dataInfo, error) {
	if di, ok := g.data[d.Name]; ok {
		return di, nil
	}
	var k kind
	switch d.Metatype {
	case "enum":
		k = kindEnum
	case "bitmap":
		k = kindBitmap
	case "object":
		k = kindStruct
	default:
		return nil, nil
	}
	di := &dataInfo{dt: d, goName: exportName(d.Name), kind: k, bits: primitiveBits(d.Primitive)}
	if err := g.claim(di.goName, "datatype "+d.Name); err != nil {
		return nil, err
	}
	g.data[d.Name] = di
	g.dataList = append(g.dataList, di)
	if k == kindStruct {
		fields, err := g.fields(d.Fields, di.goName)
		if err != nil {
			return nil, err
		}
		di.fields = fields
	}
	return di, nil
}

// collect resolves every datatype and payload the package declares.
func (g *generator) collect() error {
	for _, d := range g.c.Datatypes {
		if _, err := g.declare(d); err != nil {
			return err
		}
	}
	for _, a := range g.attributes() {
		t, err := g.resolve(&a.Effective.value, exportName(a.Name))
		if err != nil {
			return fmt.Errorf("attribute %s: %w", a.Name, err)
		}
		g.attrType[a.ID] = t
	}
	for _, cmd := range g.c.Commands {
		eff := cmd.Effective
		goName := exportName(cmd.Name)
		if eff.Direction == "request" {
			goName += "Request"
		} else if !strings.HasSuffix(goName, "Response") {
			goName += "Response"
		}
		if g.data[cmd.Name] != nil || g.used[goName] != "" {
			goName += "Command"
		}
		if err := g.claim(goName, "command "+cmd.Name); err != nil {
			return err
		}
		fields, err := g.fields(eff.Fields, goName)
		if err != nil {
			return fmt.Errorf("command %s: %w", cmd.Name, err)
		}
		p := &payload{goName: goName, what: cmd.Name, fields: fields, command: cmd}
		if eff.Direction == "response" {
			p.response = cmd
		}
		g.payloads = append(g.payloads, p)
	}
	for _, ev := range g.c.Events {
		goName := exportName(ev.Name) + "Event"
		if err := g.claim(goName, "event "+ev.Name); err != nil {
			return err
		}
		fields, err := g.fields(ev.Effective.Fields, goName)
		if err != nil {
			return fmt.Errorf("event %s: %w", ev.Name, err)
		}
		g.payloads = append(g.payloads, &payload{goName: goName, what: ev.Name, fields: fields, event: ev})
	}
	return nil
}

// attributes are the cluster's own attributes, globals excluded.
func (g *generator) attributes() []*element {
	var out []*element
	for _, a := range g.c.Attributes {
		if a.ID < globalAttributeFloor {
			out = append(out, a)
		}
	}
	return out
}

// fields resolves the members of a struct or payload. A member without a
// type (a "DoNotUse" or "Ignored" placeholder, conformance X) carries
// nothing and is left out; decoding skips its tag.
func (g *generator) fields(vs []*value, owner string) ([]*fieldInfo, error) {
	var out []*fieldInfo
	seen := map[string]bool{"EncodeTLV": true, "DecodeTLV": true, "ResponseCommand": true}
	for _, v := range vs {
		if v.Metatype == "" || v.ID == nil {
			continue
		}
		t, err := g.resolve(v, owner+exportName(v.Name))
		if err != nil {
			return nil, fmt.Errorf("field %s: %w", v.Name, err)
		}
		f := &fieldInfo{
			id: *v.ID, name: v.Name, goName: exportName(v.Name), t: t, v: v,
			mandatory: isMandatory(v.Conformance), nullable: v.Quality["nullable"],
		}
		if seen[f.goName] {
			f.goName += "Field"
		}
		seen[f.goName] = true
		out = append(out, f)
	}
	return out, nil
}

// resolve maps a value to its Go type. anonName names an anonymous struct
// the value states inline.
//
//nolint:funlen // one case per matter.js metatype
func (g *generator) resolve(v *value, anonName string) (typeInfo, error) {
	t := typeInfo{name: v.Type}
	switch v.Metatype {
	case "":
		t.kind, t.goType = kindAny, "any"
		return t, nil
	case "boolean":
		t.kind, t.goType = kindBool, "bool"
		return t, nil
	case "float":
		if v.Primitive == "double" {
			t.kind, t.goType = kindFloat64, "float64"
		} else {
			t.kind, t.goType = kindFloat32, "float32"
		}
		return t, nil
	case "string":
		t.kind, t.goType = kindString, "string"
		return t, nil
	case "bytes":
		t.kind, t.goType = kindBytes, "[]byte"
		return t, nil
	case "array":
		t.kind = kindList
		if v.Entry == nil {
			return t, fmt.Errorf("list %q states no entry type", v.Name)
		}
		et, err := g.resolve(v.Entry, anonName+"Entry")
		if err != nil {
			return t, err
		}
		elem := &fieldInfo{name: "entry", t: et, v: v.Entry, mandatory: true, nullable: v.Entry.Quality["nullable"]}
		t.elem = elem
		t.goType = "[]" + elem.goType()
		return t, nil
	case "object":
		if d := g.lookupDatatype(v.Type); d != nil && v.Type != "struct" {
			di, err := g.declare(d)
			if err != nil {
				return t, err
			}
			if di != nil {
				t.kind, t.goType, t.dt = kindStruct, di.goName, di
				return t, nil
			}
		}
		// An anonymous struct stated inline.
		if err := g.claim(anonName, "anonymous struct"); err != nil {
			return t, err
		}
		fields, err := g.fields(v.Fields, anonName)
		if err != nil {
			return t, err
		}
		di := &dataInfo{dt: &datatype{Name: v.Type, Metatype: "object"}, goName: anonName, kind: kindStruct, fields: fields}
		g.anon = append(g.anon, &payload{goName: anonName, what: anonName, fields: fields})
		t.kind, t.goType, t.dt = kindStruct, anonName, di
		return t, nil
	case "enum", "bitmap", "integer":
		bits := primitiveBits(v.Primitive)
		if bits == 0 {
			return t, fmt.Errorf("no integer width for primitive %q", v.Primitive)
		}
		t.bits = bits
		if v.Metatype != "integer" {
			if d := g.lookupDatatype(v.Type); d != nil {
				di, err := g.declare(d)
				if err != nil {
					return t, err
				}
				if di != nil {
					t.kind, t.goType, t.dt = di.kind, di.goName, di
					return t, nil
				}
			}
		}
		if strings.HasPrefix(v.Primitive, "int") {
			t.kind, t.goType = kindInt, goInt(bits, true)
		} else {
			t.kind, t.goType = kindUint, goInt(bits, false)
		}
		return t, nil
	}
	return t, fmt.Errorf("unsupported metatype %q", v.Metatype)
}

// goType is the Go type of the field, nullable wrapping included.
func (f *fieldInfo) goType() string {
	if f.nullable {
		return "spec.Nullable[" + f.t.goType + "]"
	}
	return f.t.goType
}

func primitiveBits(p string) int {
	for _, prefix := range []string{"uint", "int", "enum", "map"} {
		if rest, ok := strings.CutPrefix(p, prefix); ok {
			if n, err := strconv.Atoi(rest); err == nil {
				return n
			}
		}
	}
	return 0
}

func goInt(bits int, signed bool) string {
	w := 64
	switch {
	case bits <= 8:
		w = 8
	case bits <= 16:
		w = 16
	case bits <= 32:
		w = 32
	}
	if signed {
		return "int" + strconv.Itoa(w)
	}
	return "uint" + strconv.Itoa(w)
}

// isMandatory mirrors Conformance.isMandatory on the snapshot's AST.
func isMandatory(c *conformance) bool {
	if c == nil {
		return false
	}
	var ast struct {
		Type  string            `json:"type"`
		Param []json.RawMessage `json:"param"`
	}
	if json.Unmarshal(c.AST, &ast) != nil {
		var single struct {
			Type string `json:"type"`
		}
		_ = json.Unmarshal(c.AST, &single)
		return single.Type == "M"
	}
	switch ast.Type {
	case "M":
		return true
	case "otherwise":
		for _, p := range ast.Param {
			var t struct {
				Type string `json:"type"`
			}
			_ = json.Unmarshal(p, &t)
			switch t.Type {
			case "P":
				return false
			case "M":
				return true
			}
		}
	}
	return false
}

// ---------------------------------------------------------------------------
// Source.

type writer struct{ bytes.Buffer }

func (w *writer) p(line string, args ...any) {
	fmt.Fprintf(&w.Buffer, line, args...)
	w.WriteByte('\n')
}

//nolint:funlen // a template: the sections of a generated file in order
func (g *generator) source() ([]byte, error) {
	w := &writer{}
	c := g.c
	w.WriteString(header)
	derived := ""
	if c.Base != "" {
		derived = ", derived from " + c.Base
	}
	w.p("// Package %s is the generated definition of the Matter %s cluster", g.pkg, c.Name)
	w.p("// (0x%04X, revision %d%s), from the matter.js model at %s (Matter %s).", c.ID, c.Revision, derived, short(g.snap.Matter.SourceCommit), g.snap.Matter.Revision)
	w.p("//")
	w.p("// It declares the cluster's ids, typed enums, bitmaps and structs with their")
	w.p("// TLV codecs, the command and event payloads, and [Definition], the metadata")
	w.p("// the cluster/spec runtime derives lists, privileges and write checks from.")
	w.p("// Importing the package registers the definition with spec.Register, so the")
	w.p("// bridge decodes the cluster's request payloads.")
	w.p("package %s", g.pkg)
	w.p("")
	if g.encodes() {
		w.p("import (")
		w.p("\t\"github.com/SukramJ/go-fabric/cluster/spec\"")
		w.p("\t\"github.com/SukramJ/go-fabric/tlv\"")
		w.p(")")
	} else {
		w.p("import \"github.com/SukramJ/go-fabric/cluster/spec\"")
	}
	w.p("")
	w.p("// Cluster identity.")
	w.p("const (")
	w.p("\tClusterID uint32 = 0x%04X", c.ID)
	w.p("\tName = %q", c.Name)
	w.p("\tRevision uint16 = %d", c.Revision)
	w.p(")")
	w.p("")

	attrs := g.attributes()
	if len(attrs) > 0 {
		w.p("// Attribute ids.")
		w.p("const (")
		for _, a := range attrs {
			id := "Attr" + exportName(a.Name)
			if err := g.claim(id, "attribute "+a.Name); err != nil {
				return nil, err
			}
			w.p("\t%s uint32 = 0x%04X // %s", id, a.ID, describe(&a.Effective.value))
		}
		w.p(")")
		w.p("")
	}
	if len(c.Commands) > 0 {
		w.p("// Command ids.")
		w.p("const (")
		for _, cmd := range c.Commands {
			id := "Cmd" + exportName(cmd.Name)
			if err := g.claim(id, "command "+cmd.Name); err != nil {
				return nil, err
			}
			e := cmd.Effective
			note := e.Direction
			if e.Response != "" {
				note += " → " + e.Response
			}
			w.p("\t%s uint32 = 0x%02X // %s, %s", id, cmd.ID, note, confText(e.Conformance))
		}
		w.p(")")
		w.p("")
	}
	if len(c.Events) > 0 {
		w.p("// Event ids.")
		w.p("const (")
		for _, ev := range c.Events {
			id := "Event" + exportName(ev.Name)
			if err := g.claim(id, "event "+ev.Name); err != nil {
				return nil, err
			}
			w.p("\t%s uint32 = 0x%02X // %s, %s", id, ev.ID, ev.Effective.Priority, confText(ev.Effective.Conformance))
		}
		w.p(")")
		w.p("")
	}
	w.p("// Feature is a %s FeatureMap bit.", c.Name)
	w.p("//")
	w.p("// fabric:reachable:reason=\"generated: referenced from Definition and the generated test; a package-level initializer, which RTA does not follow\"")
	w.p("type Feature uint32")
	w.p("")
	if len(c.Features) > 0 {
		w.p("// FeatureMap bits.")
		w.p("const (")
		for _, f := range c.Features {
			id := "Feature" + exportName(featureTitle(f))
			if err := g.claim(id, "feature "+f.Name); err != nil {
				return nil, err
			}
			w.p("\t%s Feature = 1 << %d // %s, %s", id, f.Bit, f.Name, confText(f.Effective.Conformance))
		}
		w.p(")")
		w.p("")
	}

	for _, di := range g.dataList {
		if err := g.writeDatatype(w, di); err != nil {
			return nil, err
		}
	}
	for _, p := range g.anon {
		g.writePayload(w, p, "the anonymous struct "+p.what)
	}
	for _, p := range g.payloads {
		what := "the " + p.what + " event payload"
		if p.command != nil {
			what = "the " + p.what + " command payload"
		}
		g.writePayload(w, p, what)
	}
	for _, p := range g.payloads {
		w.p("func decode%s(n spec.Node) (any, error) { return spec.DecodeStruct[%s](n) }", p.goName, p.goName)
		w.p("")
	}
	for _, a := range g.attributes() {
		if dec := g.attrDecoder(a); dec != "" {
			w.p("func decodeAttr%s(n spec.Node) (any, error) {", exportName(a.Name))
			w.p("\t%s", dec)
			w.p("}")
			w.p("")
		}
	}

	g.writeDefinition(w)
	w.p("func init() { spec.Register(Definition) }")

	out, err := format.Source(w.Bytes())
	if err != nil {
		return nil, fmt.Errorf("gofmt: %w\n%s", err, w.String())
	}
	return out, nil
}

// encodes reports whether the package declares any struct or payload,
// and so a TLV codec.
func (g *generator) encodes() bool {
	if len(g.payloads) > 0 || len(g.anon) > 0 {
		return true
	}
	for _, di := range g.dataList {
		if di.kind == kindStruct {
			return true
		}
	}
	return false
}

func short(commit string) string {
	if len(commit) > 7 {
		return commit[:7]
	}
	return commit
}

func featureTitle(f *feature) string {
	if f.Effective.Title != "" {
		return f.Effective.Title
	}
	return f.Name
}

// confComment is the trailing comment of an enum value or a bitmap member:
// its conformance, when it states one.
func confComment(c *conformance) string {
	if c == nil || c.Text == "" {
		return ""
	}
	return " // " + c.Text
}

// confField is the Conformance field of a literal, left out when the
// element states none.
func confField(c *conformance) string {
	if c == nil {
		return ""
	}
	return ", Conformance: " + confLiteral(c)
}

func confText(c *conformance) string {
	if c == nil || c.Text == "" {
		return "O"
	}
	return c.Text
}

// describe is the comment of an attribute id: its type, conformance,
// access and quality.
func describe(v *value) string {
	parts := []string{typeText(v), confText(v.Conformance)}
	if a := accessText(v.Access); a != "" {
		parts = append(parts, a)
	}
	if q := qualityText(v.Quality); q != "" {
		parts = append(parts, q)
	}
	return strings.Join(parts, ", ")
}

func typeText(v *value) string {
	if v.Type == "list" && v.Entry != nil {
		return "list[" + v.Entry.Type + "]"
	}
	if v.Type == "" {
		return "untyped"
	}
	return v.Type
}

func accessText(a *access) string {
	if a == nil {
		return ""
	}
	parts := []string{}
	if a.RW != "" {
		parts = append(parts, a.RW)
	}
	if a.Fabric != "" {
		parts = append(parts, a.Fabric)
	}
	priv := a.ReadPriv
	if a.WritePriv != "" && a.WritePriv != a.ReadPriv {
		priv += a.WritePriv
	}
	if priv != "" {
		parts = append(parts, priv)
	}
	if a.Timed {
		parts = append(parts, "T")
	}
	return strings.Join(parts, " ")
}

var qualityFlags = []struct{ key, flag, field string }{
	{"nullable", "X", "Nullable"},
	{"nonvolatile", "N", "NonVolatile"},
	{"fixed", "F", "Fixed"},
	{"scene", "S", "Scene"},
	{"reportable", "P", "Reportable"},
	{"changesOmitted", "C", "ChangesOmitted"},
	{"singleton", "I", "Singleton"},
	{"quieter", "Q", "Quieter"},
	{"largeMessage", "L", "LargeMessage"},
	{"diagnostics", "K", "Diagnostics"},
	{"atomic", "T", "Atomic"},
}

func qualityText(q map[string]bool) string {
	var parts []string
	for _, f := range qualityFlags {
		if q[f.key] {
			parts = append(parts, f.flag)
		}
	}
	return strings.Join(parts, " ")
}

//nolint:funlen // a template: one section per datatype kind
func (g *generator) writeDatatype(w *writer, di *dataInfo) error {
	d := di.dt
	switch di.kind {
	case kindEnum:
		w.p("// %s is the %s %s.", di.goName, d.Name, d.Type)
		w.p("//")
		w.p("// fabric:reachable:reason=\"generated: referenced from Definition and the generated test; a package-level initializer, which RTA does not follow\"")
		w.p("type %s %s", di.goName, goInt(di.bits, false))
		w.p("")
		if len(d.Fields) > 0 {
			w.p("// %s values.", di.goName)
			w.p("const (")
			for _, f := range d.Fields {
				if f.ID == nil {
					continue
				}
				id := g.prefix(di) + exportName(f.Name)
				if err := g.claim(id, d.Name+" value "+f.Name); err != nil {
					return err
				}
				w.p("\t%s %s = %d%s", id, di.goName, *f.ID, confComment(f.Conformance))
			}
			w.p(")")
			w.p("")
		}
		w.p("// %sDef describes %s.", di.goName, d.Name)
		w.p("//")
		w.p("// fabric:reachable:reason=\"generated: referenced from Definition and the generated test; a package-level initializer, which RTA does not follow\"")
		w.p("var %sDef = &spec.Enum{Name: %q, Bits: %d, Values: []spec.EnumValue{", di.goName, d.Name, di.bits)
		for _, f := range d.Fields {
			if f.ID != nil {
				w.p("\t{Value: %d, Name: %q%s},", *f.ID, f.Name, confField(f.Conformance))
			}
		}
		w.p("}}")
		w.p("")
	case kindBitmap:
		w.p("// %s is the %s %s.", di.goName, d.Name, d.Type)
		w.p("//")
		w.p("// fabric:reachable:reason=\"generated: referenced from Definition and the generated test; a package-level initializer, which RTA does not follow\"")
		w.p("type %s %s", di.goName, goInt(di.bits, false))
		w.p("")
		type member struct {
			name        string
			bit, width  uint
			conformance *conformance
		}
		var members []member
		for _, f := range d.Fields {
			bit, width, ok := bitsOf(f.Constraint)
			if !ok {
				return fmt.Errorf("bitmap %s member %s has no bit", d.Name, f.Name)
			}
			members = append(members, member{f.Name, bit, width, f.Conformance})
		}
		if len(members) > 0 {
			w.p("// %s bits; a member wider than one bit is its mask.", di.goName)
			w.p("const (")
			for _, m := range members {
				id := g.prefix(di) + exportName(m.name)
				if err := g.claim(id, d.Name+" member "+m.name); err != nil {
					return err
				}
				if m.width == 1 {
					w.p("\t%s %s = 1 << %d%s", id, di.goName, m.bit, confComment(m.conformance))
				} else {
					w.p("\t%s %s = 0x%X // bits %d..%d%s", id, di.goName, (uint64(1)<<m.width-1)<<m.bit, m.bit, m.bit+m.width-1,
						strings.Replace(confComment(m.conformance), " //", ",", 1))
				}
			}
			w.p(")")
			w.p("")
		}
		w.p("// %sDef describes %s.", di.goName, d.Name)
		w.p("//")
		w.p("// fabric:reachable:reason=\"generated: referenced from Definition and the generated test; a package-level initializer, which RTA does not follow\"")
		w.p("var %sDef = &spec.Bitmap{Name: %q, Bits: %d, Members: []spec.BitmapMember{", di.goName, d.Name, di.bits)
		for _, m := range members {
			w.p("\t{Name: %q, Bit: %d, Width: %d%s},", m.name, m.bit, m.width, confField(m.conformance))
		}
		w.p("}}")
		w.p("")
	case kindStruct:
		g.writePayload(w, &payload{goName: di.goName, what: d.Name, fields: di.fields}, "the "+d.Name+" struct")
		w.p("// %sDef describes %s.", di.goName, d.Name)
		w.p("//")
		w.p("// fabric:reachable:reason=\"generated: referenced from Definition and the generated test; a package-level initializer, which RTA does not follow\"")
		w.p("var %sDef = &spec.Struct{Name: %q, Fields: %s}", di.goName, d.Name, g.fieldsLiteral(di.fields))
		w.p("")
	default:
	}
	return nil
}

// prefix is the prefix of a datatype's value constants: its name without
// the "Enum" / "Bitmap" suffix, unless another enum or bitmap of the
// package shortens to the same prefix (OccupancySensing has both an
// OccupancySensorTypeEnum and an OccupancySensorTypeBitmap), in which case
// both keep their full name.
func (g *generator) prefix(di *dataInfo) string {
	short := valuePrefix(di.goName)
	for _, other := range g.dataList {
		if other != di && (other.kind == kindEnum || other.kind == kindBitmap) && valuePrefix(other.goName) == short {
			return di.goName
		}
	}
	return short
}

// bitsOf reads a bitmap member's bit, or range of bits, from its
// constraint ("3", "2 to 4").
func bitsOf(c *constraint) (bit, width uint, ok bool) {
	if c == nil {
		return 0, 0, false
	}
	if n, ok := intOf(c.Value); ok {
		return uint(n), 1, true //nolint:gosec // a bit position
	}
	lo, okLo := intOf(c.Min)
	hi, okHi := intOf(c.Max)
	if okLo && okHi && hi >= lo {
		return uint(lo), uint(hi - lo + 1), true //nolint:gosec // bit positions
	}
	return 0, 0, false
}

func intOf(raw json.RawMessage) (int64, bool) {
	if len(raw) == 0 {
		return 0, false
	}
	var f float64
	if json.Unmarshal(raw, &f) != nil || f != math.Trunc(f) {
		return 0, false
	}
	return int64(f), true
}

func (g *generator) writePayload(w *writer, p *payload, what string) {
	w.p("// %s is %s.", p.goName, what)
	if len(p.fields) == 0 {
		w.p("type %s struct{}", p.goName)
	} else {
		w.p("type %s struct {", p.goName)
		for _, f := range p.fields {
			t := f.goType()
			if !f.mandatory {
				t = "*" + t
			}
			w.p("\t%s %s // %d: %s", f.goName, t, f.id, fieldNote(f))
		}
		w.p("}")
	}
	w.p("")
	w.p("// EncodeTLV implements spec.Encodable.")
	w.p("func (v %s) EncodeTLV(enc *tlv.Encoder, tag tlv.Tag) {", p.goName)
	w.p("\tenc.StartStruct(tag)")
	for _, f := range p.fields {
		put := putExpr(f)
		if f.mandatory {
			w.p("\t%s(enc, tlv.ContextTag(%d), v.%s)", put, f.id, f.goName)
		} else {
			w.p("\tspec.PutOptional(enc, tlv.ContextTag(%d), v.%s, %s)", f.id, f.goName, put)
		}
	}
	w.p("\t_ = enc.EndContainer()")
	w.p("}")
	w.p("")
	w.p("// DecodeTLV decodes the structure n into v.")
	if len(p.fields) == 0 {
		w.p("func (v *%s) DecodeTLV(n spec.Node) error { return spec.DecodeFields(n, %q) }", p.goName, p.what)
	} else {
		w.p("func (v *%s) DecodeTLV(n spec.Node) error {", p.goName)
		w.p("\treturn spec.DecodeFields(n, %q,", p.what)
		for _, f := range p.fields {
			dec := decExpr(f)
			if !f.mandatory {
				dec = "spec.DecodeOptional(" + dec + ")"
			}
			w.p("\t\tspec.Bind(%d, %q, %t, &v.%s, %s),", f.id, f.name, f.mandatory, f.goName, dec)
		}
		w.p("\t)")
		w.p("}")
	}
	w.p("")
	if p.response != nil {
		w.p("// ResponseCommand implements spec.ResponsePayload.")
		w.p("func (%s) ResponseCommand() (clusterID, commandID uint32) { return ClusterID, Cmd%s }", p.goName, exportName(p.response.Name))
		w.p("")
	}
}

func fieldNote(f *fieldInfo) string {
	parts := []string{typeText(f.v), confText(f.v.Conformance)}
	if f.v.Constraint != nil && f.v.Constraint.Text != "" {
		parts = append(parts, f.v.Constraint.Text)
	}
	if q := qualityText(f.v.Quality); q != "" {
		parts = append(parts, q)
	}
	return strings.Join(parts, ", ")
}

// putExpr is the spec.Put expression of a field's value (nullable wrapping
// included, optional wrapping not).
func putExpr(f *fieldInfo) string {
	put := basePut(f.t)
	if f.nullable {
		put = "spec.PutNullable(" + put + ")"
	}
	return put
}

func basePut(t typeInfo) string {
	switch t.kind {
	case kindBool:
		return "spec.PutBool"
	case kindUint, kindEnum, kindBitmap:
		return "spec.PutUint[" + t.goType + "]"
	case kindInt:
		return "spec.PutInt[" + t.goType + "]"
	case kindFloat32:
		return "spec.PutFloat32"
	case kindFloat64:
		return "spec.PutFloat64"
	case kindString:
		return "spec.PutString"
	case kindBytes:
		return "spec.PutBytes"
	case kindStruct:
		return "spec.PutStruct[" + t.goType + "]"
	case kindList:
		return "spec.PutList(" + putExpr(t.elem) + ")"
	default:
	}
	panic("clustergen: no encoder for kind " + string(t.kind))
}

// decExpr is the spec.Decoder expression of a field's value, bounded by its
// numeric or length constraint as TlvOfModel bounds it.
func decExpr(f *fieldInfo) string {
	dec := baseDec(f.t, f.v)
	if f.nullable {
		dec = "spec.DecodeNullable(" + dec + ")"
	}
	return dec
}

// typeBounds are the ranges matter.js's NumberMapping gives a named
// integer type beyond its width (ModelBounds.NumericRanges).
var typeBounds = map[string][2]int64{"percent": {0, 100}, "percent100ths": {0, 10000}}

func baseDec(t typeInfo, v *value) string {
	var c *constraint
	if v != nil {
		c = v.Constraint
	}
	switch t.kind {
	case kindBool:
		return "spec.DecodeBool"
	case kindUint, kindEnum, kindBitmap:
		lo, hi, ok := numericBounds(c, t.name)
		if ok && t.kind == kindUint {
			full := uint64(math.MaxUint64) >> (64 - t.bits)
			if lo < 0 {
				lo = 0
			}
			uhi := full
			if hi >= 0 && uint64(hi) < full {
				uhi = uint64(hi)
			}
			if lo > 0 || uhi < full {
				return fmt.Sprintf("spec.DecodeUintIn[%s](%d, %d, %d)", t.goType, t.bits, lo, uhi)
			}
		}
		return fmt.Sprintf("spec.DecodeUint[%s](%d)", t.goType, t.bits)
	case kindInt:
		lo, hi, ok := numericBounds(c, t.name)
		if ok {
			return fmt.Sprintf("spec.DecodeIntIn[%s](%d, %d, %d)", t.goType, t.bits, lo, hi)
		}
		return fmt.Sprintf("spec.DecodeInt[%s](%d)", t.goType, t.bits)
	case kindFloat32:
		return "spec.DecodeFloat32"
	case kindFloat64:
		return "spec.DecodeFloat64"
	case kindString:
		if lo, hi, ok := lengthBounds(c); ok {
			return fmt.Sprintf("spec.DecodeStringIn(%d, %d)", lo, hi)
		}
		return "spec.DecodeString"
	case kindBytes:
		if lo, hi, ok := lengthBounds(c); ok {
			return fmt.Sprintf("spec.DecodeBytesIn(%d, %d)", lo, hi)
		}
		return "spec.DecodeBytes"
	case kindStruct:
		return "spec.DecodeStruct[" + t.goType + "]"
	case kindList:
		entry := decExpr(t.elem)
		if lo, hi, ok := lengthBounds(c); ok {
			return fmt.Sprintf("spec.DecodeListIn(%s, %d, %d)", entry, lo, hi)
		}
		return "spec.DecodeList(" + entry + ")"
	default:
	}
	panic("clustergen: no decoder for kind " + string(t.kind))
}

// numericBounds reads the numeric bounds of a constraint ("min 1", "0 to
// 100", "8"); references and expressions are the runtime's. The bounds
// are clamped to int64; hi -1 means unbounded above.
func numericBounds(c *constraint, typeName string) (lo, hi int64, ok bool) {
	lo, hi = math.MinInt64, math.MaxInt64
	if b, has := typeBounds[typeName]; has {
		lo, hi, ok = b[0], b[1], true
	}
	if c == nil {
		return lo, hi, ok
	}
	if n, has := intOf(c.Value); has {
		return n, n, true
	}
	if n, has := intOf(c.Min); has {
		lo, ok = max(lo, n), true
	}
	if n, has := intOf(c.Max); has {
		hi, ok = min(hi, n), true
	}
	return lo, hi, ok
}

// lengthBounds reads a length constraint of a string, octet string or
// list ("max 64", "1 to 8", "16").
func lengthBounds(c *constraint) (lo, hi int, ok bool) {
	if c == nil {
		return 0, 0, false
	}
	if n, has := intOf(c.Value); has {
		return int(n), int(n), true
	}
	lo, hi = 0, math.MaxInt32
	if n, has := intOf(c.Min); has {
		lo, ok = int(n), true
	}
	if n, has := intOf(c.Max); has {
		hi, ok = int(n), true
	}
	return lo, hi, ok
}

// ---------------------------------------------------------------------------
// Definition.

// attrDecoder is the body of an attribute's value decoder, for the
// attributes whose value is a struct or a list of structs — the values the
// generated types encode; empty for any other.
func (g *generator) attrDecoder(a *element) string {
	t := g.attrType[a.ID]
	if a.Effective.Quality["nullable"] {
		return ""
	}
	f := &fieldInfo{t: t, v: &a.Effective.value}
	switch {
	case t.kind == kindStruct:
		return "return " + decExpr(f) + "(n)"
	case t.kind == kindList && t.elem.t.kind == kindStruct && !t.elem.nullable:
		return fmt.Sprintf("v, err := %s(n)\n\treturn spec.List[%s](v), err", decExpr(f), t.elem.t.goType)
	}
	return ""
}

//nolint:funlen // a template: the definition literal, section by section
func (g *generator) writeDefinition(w *writer) {
	c := g.c
	w.p("// Definition is the %s cluster definition.", c.Name)
	w.p("var Definition = &spec.Cluster{")
	w.p("\tID: ClusterID, Name: Name, Revision: Revision,")
	if c.Base != "" {
		w.p("\tBase: %q,", c.Base)
	}
	if len(c.Features) > 0 {
		w.p("\tFeatures: []spec.Feature{")
		for _, f := range c.Features {
			w.p("\t\t{Name: %q, Title: %q, Bit: %d, Conformance: %s},", f.Name, featureTitle(f), f.Bit, confLiteral(f.Effective.Conformance))
		}
		w.p("\t},")
	}
	attrs := g.attributes()
	if len(attrs) > 0 {
		w.p("\tAttributes: []spec.Attribute{")
		for _, a := range attrs {
			v := &a.Effective.value
			t := g.attrType[a.ID]
			w.p("\t\t{")
			w.p("\t\t\tID: Attr%s, Name: %q,", exportName(a.Name), a.Name)
			w.p("\t\t\tType: %s,", g.typeLiteral(t, v))
			w.p("\t\t\tConformance: %s,", confLiteral(v.Conformance))
			if lit := accessLiteral(v.Access); lit != "" {
				w.p("\t\t\tAccess: %s,", lit)
			}
			if lit := qualityLiteral(v.Quality); lit != "" {
				w.p("\t\t\tQuality: %s,", lit)
			}
			if lit := constraintLiteral(v.Constraint); lit != "" {
				w.p("\t\t\tConstraint: %s,", lit)
			}
			if lit := defaultLiteral(v.Default); lit != "" {
				w.p("\t\t\tDefault: %s,", lit)
			}
			if g.attrDecoder(a) != "" {
				w.p("\t\t\tDecode: decodeAttr%s,", exportName(a.Name))
			}
			w.p("\t\t},")
		}
		w.p("\t},")
	}
	if len(c.Commands) > 0 {
		w.p("\tCommands: []spec.Command{")
		for i, cmd := range c.Commands {
			e := cmd.Effective
			p := g.payloads[i]
			dir := "spec.Request"
			if e.Direction == "response" {
				dir = "spec.Response"
			}
			w.p("\t\t{")
			w.p("\t\t\tID: Cmd%s, Name: %q, Direction: %s,", exportName(cmd.Name), cmd.Name, dir)
			if e.Response != "" {
				w.p("\t\t\tResponse: %q,", e.Response)
			}
			w.p("\t\t\tConformance: %s,", confLiteral(e.Conformance))
			if lit := accessLiteral(e.Access); lit != "" {
				w.p("\t\t\tAccess: %s,", lit)
			}
			if len(p.fields) > 0 {
				w.p("\t\t\tFields: %s,", g.fieldsLiteral(p.fields))
			}
			w.p("\t\t\tDecode: decode%s,", p.goName)
			w.p("\t\t},")
		}
		w.p("\t},")
	}
	if len(c.Events) > 0 {
		w.p("\tEvents: []spec.Event{")
		for i, ev := range c.Events {
			e := ev.Effective
			p := g.payloads[len(c.Commands)+i]
			w.p("\t\t{")
			w.p("\t\t\tID: Event%s, Name: %q, Priority: %s,", exportName(ev.Name), ev.Name, priorityLiteral(e.Priority))
			w.p("\t\t\tConformance: %s,", confLiteral(e.Conformance))
			if lit := accessLiteral(e.Access); lit != "" {
				w.p("\t\t\tAccess: %s,", lit)
			}
			if len(p.fields) > 0 {
				w.p("\t\t\tFields: %s,", g.fieldsLiteral(p.fields))
			}
			w.p("\t\t\tDecode: decode%s,", p.goName)
			w.p("\t\t},")
		}
		w.p("\t},")
	}
	w.p("}")
	w.p("")
}

func priorityLiteral(p string) string {
	switch p {
	case "critical":
		return "spec.PriorityCritical"
	case "debug":
		return "spec.PriorityDebug"
	}
	return "spec.PriorityInfo"
}

var kindLiteral = map[kind]string{
	kindAny: "spec.KindAny", kindBool: "spec.KindBool", kindUint: "spec.KindUint", kindInt: "spec.KindInt",
	kindFloat32: "spec.KindFloat32", kindFloat64: "spec.KindFloat64", kindString: "spec.KindString",
	kindBytes: "spec.KindBytes", kindEnum: "spec.KindEnum", kindBitmap: "spec.KindBitmap",
	kindStruct: "spec.KindStruct", kindList: "spec.KindList",
}

func (g *generator) typeLiteral(t typeInfo, v *value) string {
	parts := []string{fmt.Sprintf("Name: %q", t.name), "Kind: " + kindLiteral[t.kind]}
	if t.bits != 0 {
		parts = append(parts, fmt.Sprintf("Bits: %d", t.bits))
	}
	if t.dt != nil {
		switch t.kind {
		case kindEnum:
			parts = append(parts, "Enum: "+t.dt.goName+"Def")
		case kindBitmap:
			parts = append(parts, "Bitmap: "+t.dt.goName+"Def")
		case kindStruct:
			if g.data[t.dt.dt.Name] == t.dt {
				parts = append(parts, "Struct: "+t.dt.goName+"Def")
			} else {
				parts = append(parts, fmt.Sprintf("Struct: &spec.Struct{Name: %q, Fields: %s}", t.dt.goName, g.fieldsLiteral(t.dt.fields)))
			}
		default:
		}
	}
	if t.kind == kindList && t.elem != nil {
		parts = append(parts, "Entry: &"+g.fieldLiteral(t.elem))
	}
	_ = v
	return "spec.Type{" + strings.Join(parts, ", ") + "}"
}

func (g *generator) fieldsLiteral(fields []*fieldInfo) string {
	if len(fields) == 0 {
		return "nil"
	}
	parts := make([]string, 0, len(fields))
	for _, f := range fields {
		parts = append(parts, strings.TrimPrefix(g.fieldLiteral(f), "spec.Field"))
	}
	return "[]spec.Field{\n" + strings.Join(parts, ",\n") + ",\n}"
}

func (g *generator) fieldLiteral(f *fieldInfo) string {
	parts := []string{}
	if f.name != "entry" {
		parts = append(parts, fmt.Sprintf("ID: %d", f.id))
	}
	parts = append(parts, fmt.Sprintf("Name: %q", f.name), "Type: "+g.typeLiteral(f.t, f.v))
	if f.v != nil {
		if f.v.Conformance != nil {
			parts = append(parts, "Conformance: "+confLiteral(f.v.Conformance))
		}
		if lit := qualityLiteral(f.v.Quality); lit != "" {
			parts = append(parts, "Quality: "+lit)
		}
		if lit := constraintLiteral(f.v.Constraint); lit != "" {
			parts = append(parts, "Constraint: "+lit)
		}
		if f.v.Access != nil && f.v.Access.Fabric == "S" {
			parts = append(parts, "FabricSensitive: true")
		}
		if lit := defaultLiteral(f.v.Default); lit != "" {
			parts = append(parts, "Default: "+lit)
		}
	}
	return "spec.Field{" + strings.Join(parts, ", ") + "}"
}

var privilegeLiteral = map[string]string{
	"V": "spec.PrivilegeView", "P": "spec.PrivilegeProxyView", "O": "spec.PrivilegeOperate",
	"M": "spec.PrivilegeManage", "A": "spec.PrivilegeAdminister",
}

func accessLiteral(a *access) string {
	if a == nil {
		return ""
	}
	var parts []string
	if a.RW != "" {
		parts = append(parts, fmt.Sprintf("RW: %q", a.RW))
	}
	if p := privilegeLiteral[a.ReadPriv]; p != "" {
		parts = append(parts, "Read: "+p)
	}
	if p := privilegeLiteral[a.WritePriv]; p != "" {
		parts = append(parts, "Write: "+p)
	}
	if a.Fabric != "" {
		parts = append(parts, fmt.Sprintf("Fabric: %q", a.Fabric))
	}
	if a.Timed {
		parts = append(parts, "Timed: true")
	}
	if len(parts) == 0 {
		return ""
	}
	return "spec.Access{" + strings.Join(parts, ", ") + "}"
}

func qualityLiteral(q map[string]bool) string {
	var parts []string
	for _, f := range qualityFlags {
		if q[f.key] {
			parts = append(parts, f.field+": true")
		}
	}
	if len(parts) == 0 {
		return ""
	}
	return "spec.Quality{" + strings.Join(parts, ", ") + "}"
}

func constraintLiteral(c *constraint) string {
	if c == nil {
		return ""
	}
	parts := []string{fmt.Sprintf("Text: %q", c.Text)}
	if c.Desc {
		parts = append(parts, "Desc: true")
	}
	for _, b := range []struct {
		name string
		raw  json.RawMessage
	}{{"Value", c.Value}, {"Min", c.Min}, {"Max", c.Max}} {
		if lit := boundLiteral(b.raw); lit != "" {
			parts = append(parts, b.name+": "+lit)
		}
	}
	if ref := referenceOf(c.In); ref != "" {
		parts = append(parts, fmt.Sprintf("In: %q", ref))
	}
	if c.Entry != nil {
		if lit := constraintLiteral(c.Entry); lit != "" {
			parts = append(parts, "Entry: &"+lit)
		}
	}
	if len(c.Parts) > 0 {
		ps := make([]string, 0, len(c.Parts))
		for _, p := range c.Parts {
			if lit := constraintLiteral(p); lit != "" {
				ps = append(ps, strings.TrimPrefix(lit, "spec.Constraint"))
			}
		}
		parts = append(parts, "Parts: []spec.Constraint{"+strings.Join(ps, ", ")+"}")
	}
	return "spec.Constraint{" + strings.Join(parts, ", ") + "}"
}

func boundLiteral(raw json.RawMessage) string {
	if len(raw) == 0 {
		return ""
	}
	if n, ok := intOf(raw); ok {
		return fmt.Sprintf("&spec.Bound{Int: %d}", n)
	}
	if ref := referenceOf(raw); ref != "" {
		return fmt.Sprintf("&spec.Bound{Ref: %q}", ref)
	}
	var compact bytes.Buffer
	if json.Compact(&compact, raw) != nil {
		compact.Reset()
		compact.Write(raw)
	}
	return fmt.Sprintf("&spec.Bound{Expr: %q}", compact.String())
}

// referenceOf reads a FieldValue reference ({"type":"reference","name":…}).
func referenceOf(raw json.RawMessage) string {
	var ref struct {
		Type string `json:"type"`
		Name string `json:"name"`
	}
	if len(raw) == 0 || json.Unmarshal(raw, &ref) != nil || ref.Type != "reference" {
		return ""
	}
	return ref.Name
}

func defaultLiteral(raw json.RawMessage) string {
	if len(raw) == 0 {
		return ""
	}
	var v any
	if json.Unmarshal(raw, &v) != nil {
		return ""
	}
	switch x := v.(type) {
	case nil:
		return "spec.NullDefault{}"
	case bool:
		return strconv.FormatBool(x)
	case float64:
		return "float64(" + strconv.FormatFloat(x, 'g', -1, 64) + ")"
	case string:
		return strconv.Quote(x)
	}
	return ""
}

// confLiteral renders a conformance AST as a spec.Conformance literal.
func confLiteral(c *conformance) string {
	if c == nil {
		return "spec.Conformance{}"
	}
	body, err := astLiteral(c.AST)
	if err != nil {
		return fmt.Sprintf("spec.Conformance{Text: %q, Op: spec.ConfDesc}", c.Text)
	}
	return fmt.Sprintf("spec.Conformance{Text: %q, %s}", c.Text, body)
}

var opLiteral = map[string]string{
	"M": "spec.ConfMandatory", "O": "spec.ConfOptional", "P": "spec.ConfProvisional", "D": "spec.ConfDeprecated",
	"X": "spec.ConfDisallowed", "Z": "spec.ConfObsolete", "empty": "spec.ConfEmpty", "desc": "spec.ConfDesc",
	"name": "spec.ConfName", "value": "spec.ConfValue", "choice": "spec.ConfChoice", "otherwise": "spec.ConfOtherwise",
	"optionalIf": "spec.ConfOptionalIf", "revision": "spec.ConfRevision", "!": "spec.ConfNot", "==": "spec.ConfEq",
	"!=": "spec.ConfNe", "|": "spec.ConfOr", "^": "spec.ConfXor", "&": "spec.ConfAnd", ".": "spec.ConfDot",
	">": "spec.ConfGt", "<": "spec.ConfLt", ">=": "spec.ConfGte", "<=": "spec.ConfLte",
}

// astLiteral renders the fields of one AST node (without the braces).
//
//nolint:funlen // one case per conformance node type
func astLiteral(raw json.RawMessage) (string, error) {
	var node struct {
		Type  string          `json:"type"`
		Param json.RawMessage `json:"param"`
	}
	if err := json.Unmarshal(raw, &node); err != nil {
		return "", err
	}
	op, ok := opLiteral[node.Type]
	if !ok {
		return "", fmt.Errorf("unknown conformance node %q", node.Type)
	}
	parts := []string{"Op: " + op}
	child := func(r json.RawMessage) (string, error) {
		body, err := astLiteral(r)
		if err != nil {
			return "", err
		}
		return "{" + body + "}", nil
	}
	switch node.Type {
	case "name":
		var name string
		if err := json.Unmarshal(node.Param, &name); err != nil {
			return "", err
		}
		parts = append(parts, fmt.Sprintf("Name: %q", name))
	case "value":
		parts = append(parts, fmt.Sprintf("Value: %q", string(node.Param)))
	case "revision":
		var rev int
		if err := json.Unmarshal(node.Param, &rev); err != nil {
			return "", err
		}
		parts = append(parts, fmt.Sprintf("Rev: %d", rev))
	case "choice":
		var ch struct {
			Name   string          `json:"name"`
			Num    int             `json:"num"`
			OrMore bool            `json:"orMore"`
			OrLess bool            `json:"orLess"`
			Expr   json.RawMessage `json:"expr"`
		}
		if err := json.Unmarshal(node.Param, &ch); err != nil {
			return "", err
		}
		parts = append(parts, fmt.Sprintf("Choice: &spec.Choice{Name: %q, Num: %d, OrMore: %t, OrLess: %t}", ch.Name, ch.Num, ch.OrMore, ch.OrLess))
		e, err := child(ch.Expr)
		if err != nil {
			return "", err
		}
		parts = append(parts, "Args: []spec.Conformance{"+e+"}")
	case "otherwise":
		var terms []json.RawMessage
		if err := json.Unmarshal(node.Param, &terms); err != nil {
			return "", err
		}
		args := make([]string, 0, len(terms))
		for _, t := range terms {
			e, err := child(t)
			if err != nil {
				return "", err
			}
			args = append(args, e)
		}
		parts = append(parts, "Args: []spec.Conformance{"+strings.Join(args, ", ")+"}")
	case "optionalIf", "!":
		e, err := child(node.Param)
		if err != nil {
			return "", err
		}
		parts = append(parts, "Args: []spec.Conformance{"+e+"}")
	case "==", "!=", "|", "^", "&", ".", ">", "<", ">=", "<=":
		var bin struct {
			LHS json.RawMessage `json:"lhs"`
			RHS json.RawMessage `json:"rhs"`
		}
		if err := json.Unmarshal(node.Param, &bin); err != nil {
			return "", err
		}
		l, err := child(bin.LHS)
		if err != nil {
			return "", err
		}
		r, err := child(bin.RHS)
		if err != nil {
			return "", err
		}
		parts = append(parts, "Args: []spec.Conformance{"+l+", "+r+"}")
	}
	return strings.Join(parts, ", "), nil
}

// ---------------------------------------------------------------------------
// Generated test.

func (g *generator) test() ([]byte, error) {
	w := &writer{}
	w.WriteString(header)
	w.p("package %s", g.pkg)
	w.p("")
	w.p("import (")
	w.p("\t\"testing\"")
	w.p("")
	w.p("\t\"github.com/SukramJ/go-fabric/cluster/spec\"")
	w.p("\t\"github.com/SukramJ/go-fabric/cluster/spec/spectest\"")
	w.p(")")
	w.p("")
	w.p("var _ = spec.Register")
	w.p("")
	w.p("// TestDefinitionMatchesSnapshot holds the generated definition against")
	w.p("// the matter.js snapshot it was generated from.")
	w.p("func TestDefinitionMatchesSnapshot(t *testing.T) {")
	w.p("\tt.Parallel()")
	w.p("\tspectest.CheckDefinition(t, Definition)")
	w.p("}")
	w.p("")
	w.p("// TestCodecsRoundTrip encodes a populated value of every generated")
	w.p("// struct and payload and decodes it back.")
	w.p("func TestCodecsRoundTrip(t *testing.T) {")
	w.p("\tt.Parallel()")
	var structs []*payload
	for _, di := range g.dataList {
		if di.kind == kindStruct {
			structs = append(structs, &payload{goName: di.goName, fields: di.fields})
		}
	}
	structs = append(structs, g.anon...)
	for _, p := range structs {
		w.p("\tspectest.RoundTrip(t, %s, spec.DecodeStruct[%s])", g.sample(p, 0), p.goName)
	}
	for _, p := range g.payloads {
		switch {
		case p.response != nil:
			w.p("\tspectest.RoundTripCommand(t, Definition, Cmd%s, spec.Response, %s)", exportName(p.command.Name), g.sample(p, 0))
		case p.command != nil:
			w.p("\tspectest.RoundTripCommand(t, Definition, Cmd%s, spec.Request, %s)", exportName(p.command.Name), g.sample(p, 0))
		default:
			w.p("\tspectest.RoundTripEvent(t, Definition, Event%s, %s)", exportName(p.event.Name), g.sample(p, 0))
		}
	}
	for _, a := range g.attributes() {
		if g.attrDecoder(a) == "" {
			continue
		}
		t := g.attrType[a.ID]
		sample := g.sampleType(t, &a.Effective.value, 0)
		if t.kind == kindList {
			sample = "spec.List[" + t.elem.t.goType + "](" + sample + ")"
		}
		w.p("\tspectest.RoundTripAttribute(t, Definition, Attr%s, %s)", exportName(a.Name), sample)
	}
	w.p("}")
	out, err := format.Source(w.Bytes())
	if err != nil {
		return nil, fmt.Errorf("gofmt test: %w\n%s", err, w.String())
	}
	return out, nil
}

// sample is a Go expression of a populated value of p: every optional
// field present, every list one entry long (or as long as its minimum).
func (g *generator) sample(p *payload, depth int) string {
	if len(p.fields) == 0 {
		return p.goName + "{}"
	}
	parts := make([]string, 0, len(p.fields))
	for _, f := range p.fields {
		v := g.sampleField(f, depth)
		if !f.mandatory {
			v = "spectest.Ptr(" + v + ")"
		}
		parts = append(parts, f.goName+": "+v)
	}
	return p.goName + "{" + strings.Join(parts, ", ") + "}"
}

func (g *generator) sampleField(f *fieldInfo, depth int) string {
	v := g.sampleType(f.t, f.v, depth)
	if f.nullable {
		return "spec.ValueOf(" + v + ")"
	}
	return v
}

func (g *generator) sampleType(t typeInfo, v *value, depth int) string {
	var c *constraint
	if v != nil {
		c = v.Constraint
	}
	switch t.kind {
	case kindBool:
		return "true"
	case kindUint, kindInt:
		n := int64(1)
		if lo, hi, ok := numericBounds(c, t.name); ok {
			n = max(min(n, hi), lo)
		}
		return fmt.Sprintf("%s(%d)", t.goType, n)
	case kindEnum:
		if t.dt != nil && len(t.dt.dt.Fields) > 0 && t.dt.dt.Fields[0].ID != nil {
			return fmt.Sprintf("%s(%d)", t.goType, *t.dt.dt.Fields[0].ID)
		}
		return t.goType + "(0)"
	case kindBitmap:
		if t.dt != nil && len(t.dt.dt.Fields) > 0 {
			if bit, _, ok := bitsOf(t.dt.dt.Fields[0].Constraint); ok {
				return fmt.Sprintf("%s(1 << %d)", t.goType, bit)
			}
		}
		return t.goType + "(0)"
	case kindFloat32:
		return "float32(1.5)"
	case kindFloat64:
		return "float64(1.5)"
	case kindString:
		n := 1
		if lo, hi, ok := lengthBounds(c); ok {
			n = max(min(n, hi), lo)
		}
		return strconv.Quote(strings.Repeat("x", n))
	case kindBytes:
		n := 1
		if lo, hi, ok := lengthBounds(c); ok {
			n = max(min(n, hi), lo)
		}
		return "[]byte{" + strings.TrimSuffix(strings.Repeat("1, ", n), ", ") + "}"
	case kindStruct:
		if depth > 3 {
			return t.goType + "{}"
		}
		return g.sample(&payload{goName: t.goType, fields: t.dt.fields}, depth+1)
	case kindList:
		n := 1
		if lo, hi, ok := lengthBounds(c); ok {
			n = max(min(n, hi), lo)
		}
		if n == 0 {
			return t.goType + "{}"
		}
		entries := make([]string, n)
		for i := range entries {
			entries[i] = g.sampleField(t.elem, depth)
		}
		return t.goType + "{" + strings.Join(entries, ", ") + "}"
	default:
	}
	return "nil"
}

// sortedClusterNames lists the snapshot's clusters by id.
func sortedClusterNames(s *snapshot) []string {
	cs := slices.Clone(s.Clusters)
	sort.Slice(cs, func(i, j int) bool { return cs[i].ID < cs[j].ID })
	out := make([]string, 0, len(cs))
	for _, c := range cs {
		out = append(out, c.Name)
	}
	return out
}
